scan_table_check.script:
(function(engine, current) {
    var reopened = new global.EcsUpdateSet(current).reopenedOn();
    if (!reopened) {
        return;
    }
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CFG-006',
        title: 'Update set reopened after completion',
        recommendation: 'If this update set was already retrieved into another instance, changes made after ' +
            'reopening will not reach it. Put new changes in a new update set, or complete this one again and ' +
            're-retrieve it everywhere it was loaded.',
        current: current
    });
    report.addRecord('Update set "' + current.getValue('name') + '" is in progress but was previously Complete ' +
        '(reopened on ' + reopened + ').');
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
